package server_test

import (
	"fmt"
	"path/filepath"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/kopia/kopia/internal/apiclient"
	"github.com/kopia/kopia/internal/repotesting"
	"github.com/kopia/kopia/internal/serverapi"
	"github.com/kopia/kopia/internal/servertesting"
	"github.com/kopia/kopia/internal/testutil"
	"github.com/kopia/kopia/repo/compression"
	"github.com/kopia/kopia/snapshot"
	"github.com/kopia/kopia/snapshot/policy"
)

func TestPolicies(t *testing.T) {
	ctx, env := repotesting.NewEnvironment(t, repotesting.FormatNotImportant)
	srvInfo := servertesting.StartServer(t, env, false)

	cli, err := apiclient.NewKopiaAPIClient(apiclient.Options{
		BaseURL:                             srvInfo.BaseURL,
		TrustedServerCertificateFingerprint: srvInfo.TrustedServerCertificateFingerprint,
		Username:                            servertesting.TestUIUsername,
		Password:                            servertesting.TestUIPassword,
	})

	require.NoError(t, err)
	require.NoError(t, cli.FetchCSRFTokenForTesting(ctx))

	dir0 := testutil.TempDirectory(t)
	si0 := env.LocalPathSourceInfo(dir0)

	dir1 := testutil.TempDirectory(t)
	si1 := env.LocalPathSourceInfo(dir1)

	dir2 := filepath.Join(dir1, "subdir1")
	si2 := env.LocalPathSourceInfo(dir2)

	dir3 := filepath.Join(dir2, "subdir2")
	si3 := env.LocalPathSourceInfo(dir3)

	dir4 := filepath.Join(dir3, "subdir3")
	si4 := env.LocalPathSourceInfo(dir4)

	mustSetPolicy(t, cli, si1, &policy.Policy{
		CompressionPolicy: policy.CompressionPolicy{
			CompressorName: "some-compressor",
		},
	})

	mustSetPolicy(t, cli, si2, &policy.Policy{
		CompressionPolicy: policy.CompressionPolicy{
			NeverCompress: []string{"a", "b"},
		},
		SchedulingPolicy: policy.SchedulingPolicy{
			IntervalSeconds: 60,
		},
	})

	mustSetPolicy(t, cli, si3, &policy.Policy{
		CompressionPolicy: policy.CompressionPolicy{
			CompressorName: "some-compressor3",
		},
	})

	cases := []struct {
		si                              snapshot.SourceInfo
		updates                         *policy.Policy
		wantCompressorName              compression.Name
		wantCompressorNameSource        snapshot.SourceInfo
		wantNeverCompress               []string
		wantNeverCompressSource         snapshot.SourceInfo
		wantUpcomingSnapshotTimesLength int
		wantSchedulingError             string
	}{
		{
			si:                       si0,
			wantCompressorName:       compression.Name("none"),
			wantNeverCompress:        nil,
			wantCompressorNameSource: policy.GlobalPolicySourceInfo,
			wantNeverCompressSource:  policy.GlobalPolicySourceInfo,
		},
		{
			si:                       si1,
			wantCompressorName:       compression.Name("some-compressor"),
			wantNeverCompress:        nil,
			wantCompressorNameSource: si1,
			wantNeverCompressSource:  policy.GlobalPolicySourceInfo,
		},
		{
			si:                       si1,
			wantCompressorName:       compression.Name("some-compressor-updated"),
			wantNeverCompress:        nil,
			wantCompressorNameSource: si1,
			wantNeverCompressSource:  policy.GlobalPolicySourceInfo,
			updates: &policy.Policy{
				CompressionPolicy: policy.CompressionPolicy{
					CompressorName: "some-compressor-updated",
				},
			},
		},
		{
			si:                              si2,
			wantCompressorName:              compression.Name("some-compressor"), // inherited
			wantNeverCompress:               []string{"a", "b"},
			wantCompressorNameSource:        si1,
			wantNeverCompressSource:         si2,
			wantUpcomingSnapshotTimesLength: 3,
		},
		{
			si:                              si3,
			wantCompressorName:              compression.Name("some-compressor3"),
			wantNeverCompress:               []string{"a", "b"},
			wantCompressorNameSource:        si3,
			wantNeverCompressSource:         si2,
			wantUpcomingSnapshotTimesLength: 3,
		},
		{
			si:                              si4,
			wantCompressorName:              compression.Name("some-compressor3"),
			wantNeverCompress:               []string{"a", "b"},
			wantCompressorNameSource:        si3,
			wantNeverCompressSource:         si2,
			wantUpcomingSnapshotTimesLength: 3,
		},
		{
			si:                       si4,
			wantCompressorName:       compression.Name("some-compressor-updated"),
			wantNeverCompress:        []string{"a", "b"},
			wantCompressorNameSource: si4,
			wantNeverCompressSource:  si2,
			updates: &policy.Policy{
				CompressionPolicy: policy.CompressionPolicy{
					CompressorName: "some-compressor-updated",
				},
			},
			wantUpcomingSnapshotTimesLength: 3,
		},
		{
			si:                       si0,
			wantCompressorName:       compression.Name("none"),
			wantNeverCompress:        nil,
			wantCompressorNameSource: policy.GlobalPolicySourceInfo,
			wantNeverCompressSource:  policy.GlobalPolicySourceInfo,
			updates: &policy.Policy{
				SchedulingPolicy: policy.SchedulingPolicy{
					Cron: []string{"invalid"},
				},
			},
			wantSchedulingError: "invalid cron expression \"invalid\"",
		},
	}

	for i, tc := range cases {
		t.Run(fmt.Sprintf("case-%v", i), func(t *testing.T) {
			res, err2 := serverapi.ResolvePolicy(ctx, cli, tc.si, &serverapi.ResolvePolicyRequest{
				Updates:                  tc.updates,
				NumUpcomingSnapshotTimes: 3,
			})
			require.NoError(t, err2)
			require.Equal(t, tc.wantCompressorName, res.Effective.CompressionPolicy.CompressorName)
			require.Equal(t, tc.wantNeverCompress, res.Effective.CompressionPolicy.NeverCompress)
			require.Equal(t, tc.wantCompressorNameSource, res.Definition.CompressionPolicy.CompressorName)
			require.Equal(t, tc.wantNeverCompressSource, res.Definition.CompressionPolicy.NeverCompress)
			require.Len(t, res.UpcomingSnapshotTimes, tc.wantUpcomingSnapshotTimesLength)
			require.Equal(t, tc.wantSchedulingError, res.SchedulingError)

			for j, ust := range res.UpcomingSnapshotTimes {
				require.Equal(t, ust.Truncate(60*time.Second), ust)

				if j > 0 {
					require.Equal(t, 60*time.Second, ust.Sub(res.UpcomingSnapshotTimes[j-1]))
				}
			}
		})
	}
}

package cache

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/pkg/errors"
	"github.com/stretchr/testify/require"

	"github.com/kopia/kopia/internal/testlogging"
	"github.com/kopia/kopia/internal/testutil"
)

func TestNewStorageOrNil(t *testing.T) {
	ctx := testlogging.Context(t)

	// empty cache dir
	st, err := NewStorageOrNil(ctx, "", 1000, "subdir")
	require.NoError(t, err)
	require.Nil(t, st)

	// zero size
	st, err = NewStorageOrNil(ctx, testutil.TempDirectory(t), 0, "subdir")
	require.NoError(t, err)
	require.Nil(t, st)

	_, err = NewStorageOrNil(ctx, "relative/path/to/cache/dir", 1000, "subdir")
	require.Error(t, err)

	someError := errors.New("some error")

	oldMkdirAll := mkdirAll

	mkdirAll = func(path string, mode os.FileMode) error {
		return someError
	}

	defer func() {
		mkdirAll = oldMkdirAll
	}()

	_, err = NewStorageOrNil(ctx, filepath.Join(testutil.TempDirectory(t), "some-subdir"), 1000, "subdir")

	require.ErrorIs(t, err, someError)
}

package cacheprot_test

import (
	"bytes"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/kopia/kopia/internal/cacheprot"
	"github.com/kopia/kopia/internal/gather"
)

func TestNoStorageProtection(t *testing.T) {
	testStorageProtection(t, cacheprot.NoProtection(), false)
}

func TestHMACStorageProtection(t *testing.T) {
	testStorageProtection(t, cacheprot.ChecksumProtection([]byte{1, 2, 3, 4}), true)
}

func TestEncryptionStorageProtection(t *testing.T) {
	e, err := cacheprot.AuthenticatedEncryptionProtection([]byte{1})
	require.NoError(t, err)

	testStorageProtection(t, e, true)
}

//nolint:thelper
func testStorageProtection(t *testing.T, sp cacheprot.StorageProtection, protectsFromBitFlips bool) {
	payload := []byte{0, 1, 2, 3, 4}

	var protected gather.WriteBuffer
	defer protected.Close()

	// append dummy bytes to ensure Reset is called.
	protected.Append([]byte("dummy"))

	sp.Protect("x", gather.FromSlice(payload), &protected)

	var unprotected gather.WriteBuffer
	defer unprotected.Close()

	// append dummy bytes to ensure Reset is called.
	unprotected.Append([]byte("dummy"))

	require.NoError(t, sp.Verify("x", protected.Bytes(), &unprotected))

	if got, want := unprotected.ToByteSlice(), payload; !bytes.Equal(got, want) {
		t.Fatalf("invalid unprotected payload %x, wanted %x", got, want)
	}

	pb := protected.ToByteSlice()

	if protectsFromBitFlips {
		// flip one bit
		pb[0] ^= 1

		require.Error(t, sp.Verify("x", gather.FromSlice(pb), &unprotected))
	} else {
		require.NoError(t, sp.Verify("x", gather.FromSlice(pb), &unprotected))
	}
}

package server

import (
	"context"
	"encoding/json"
	"net/url"
	"time"

	"github.com/pkg/errors"

	"github.com/kopia/kopia/internal/clock"
	"github.com/kopia/kopia/internal/serverapi"
	"github.com/kopia/kopia/repo"
	"github.com/kopia/kopia/snapshot"
	"github.com/kopia/kopia/snapshot/policy"
)

func handlePolicyList(ctx context.Context, rc requestContext) (any, *apiError) {
	policies, err := policy.ListPolicies(ctx, rc.rep)
	if err != nil {
		return nil, internalServerError(err)
	}

	resp := &serverapi.PoliciesResponse{
		Policies: []*serverapi.PolicyListEntry{},
	}

	for _, pol := range policies {
		target := pol.Target()
		if !sourceMatchesURLFilter(target, rc.req.URL.Query()) {
			continue
		}

		resp.Policies = append(resp.Policies, &serverapi.PolicyListEntry{
			ID:     pol.ID(),
			Target: target,
			Policy: pol,
		})
	}

	return resp, nil
}

func getSnapshotSourceFromURL(u *url.URL) snapshot.SourceInfo {
	host := u.Query().Get("host")
	path := u.Query().Get("path")
	username := u.Query().Get("userName")

	return snapshot.SourceInfo{
		Host:     host,
		Path:     path,
		UserName: username,
	}
}

func handlePolicyGet(ctx context.Context, rc requestContext) (any, *apiError) {
	pol, err := policy.GetDefinedPolicy(ctx, rc.rep, getSnapshotSourceFromURL(rc.req.URL))
	if errors.Is(err, policy.ErrPolicyNotFound) {
		return nil, requestError(serverapi.ErrorNotFound, "policy not found")
	}

	return pol, nil
}

func handlePolicyResolve(ctx context.Context, rc requestContext) (any, *apiError) {
	var req serverapi.ResolvePolicyRequest

	if err := json.Unmarshal(rc.body, &req); err != nil {
		return nil, unableToDecodeRequest(err)
	}

	target := getSnapshotSourceFromURL(rc.req.URL)

	// build a list of parents
	policies, err := policy.GetPolicyHierarchy(ctx, rc.rep, target, nil)
	if err != nil {
		return nil, internalServerError(err)
	}

	resp := &serverapi.ResolvePolicyResponse{
		Defined: policies[0],
	}

	if req.Updates != nil {
		policies[0] = req.Updates
		policies[0].Labels = policy.LabelsForSource(target)
	}

	resp.Effective, resp.Definition = policy.MergePolicies(policies, target)
	resp.UpcomingSnapshotTimes = []time.Time{}

	if err := policy.ValidateSchedulingPolicy(policies[0].SchedulingPolicy); err != nil {
		resp.SchedulingError = err.Error()
	}

	now := clock.Now().Local()

	for range req.NumUpcomingSnapshotTimes {
		st, ok := resp.Effective.SchedulingPolicy.NextSnapshotTime(now, now)
		if !ok {
			break
		}

		resp.UpcomingSnapshotTimes = append(resp.UpcomingSnapshotTimes, st)
		now = st.Add(1 * time.Second)
	}

	return resp, nil
}

func handlePolicyDelete(ctx context.Context, rc requestContext) (any, *apiError) {
	if _, ok := rc.rep.(repo.RepositoryWriter); !ok {
		return nil, repositoryNotWritableError()
	}

	sourceInfo := getSnapshotSourceFromURL(rc.req.URL)

	if err := repo.WriteSession(ctx, rc.rep, repo.WriteSessionOptions{
		Purpose: "PolicyDelete",
	}, func(ctx context.Context, w repo.RepositoryWriter) error {
		return errors.Wrap(policy.RemovePolicy(ctx, w, sourceInfo), "unable to delete policy")
	}); err != nil {
		return nil, internalServerError(err)
	}

	rc.srv.Refresh()

	return &serverapi.Empty{}, nil
}

func handlePolicyPut(ctx context.Context, rc requestContext) (any, *apiError) {
	newPolicy := &policy.Policy{}
	if err := json.Unmarshal(rc.body, newPolicy); err != nil {
		return nil, requestError(serverapi.ErrorMalformedRequest, "malformed request body")
	}

	if _, ok := rc.rep.(repo.RepositoryWriter); !ok {
		return nil, repositoryNotWritableError()
	}

	sourceInfo := getSnapshotSourceFromURL(rc.req.URL)

	if err := repo.WriteSession(ctx, rc.rep, repo.WriteSessionOptions{
		Purpose: "PolicyPut",
	}, func(ctx context.Context, w repo.RepositoryWriter) error {
		return errors.Wrap(policy.SetPolicy(ctx, w, sourceInfo, newPolicy), "unable to set policy")
	}); err != nil {
		return nil, internalServerError(err)
	}

	rc.srv.Refresh()

	return &serverapi.Empty{}, nil
}

// Command testingaction implements a action that is used in various tests.
package main

import (
	"bufio"
	"flag"
	"io"
	"log"
	"os"
	"strings"
	"time"

	"github.com/pkg/errors"
)

var (
	exitCode              = flag.Int("exit-code", 0, "Exit code")
	sleepDuration         = flag.Duration("sleep", 0, "Sleep duration")
	saveEnvironmentToFile = flag.String("save-env", "", "Save environment to file (key=value).")
	copyFilesSpec         = flag.String("copy-files", "", "Copy files based on spec in the provided file (each line containing 'source => destination')")
	createFile            = flag.String("create-file", "", "Create empty file with a given name")
	writeToStdout         = flag.String("stdout-file", "", "Copy contents of the provided file to stdout.")
	writeToStderr         = flag.String("stderr-file", "", "Copy contents of the provided file to stderr.")
)

func main() {
	flag.Parse()

	if fn := *saveEnvironmentToFile; fn != "" {
		if err := os.WriteFile(fn, []byte(strings.Join(os.Environ(), "\n")), 0o600); err != nil {
			log.Fatalf("error writing environment file: %v", err)
		}
	}

	if fn := *writeToStdout; fn != "" {
		if err := writeFileTo(os.Stdout, fn); err != nil {
			log.Fatalf("error writing to stdout: %v", err)
		}
	}

	if fn := *writeToStderr; fn != "" {
		if err := writeFileTo(os.Stderr, fn); err != nil {
			log.Fatalf("error writing to stderr: %v", err)
		}
	}

	if fn := *copyFilesSpec; fn != "" {
		if err := copyFiles(fn); err != nil {
			log.Fatalf("unable to copy files: %v", err)
		}
	}

	if fn := *createFile; fn != "" {
		if _, err := os.Stat(fn); !os.IsNotExist(err) {
			log.Fatalf("unexpected file found: %v", fn)
		}

		if err := os.WriteFile(fn, nil, 0o600); err != nil {
			log.Fatalf("unable to create file: %v", err)
		}
	}

	time.Sleep(*sleepDuration)
	os.Exit(*exitCode)
}

func writeFileTo(dst io.Writer, fn string) error {
	f, err := os.Open(fn)
	if err != nil {
		return err
	}

	defer f.Close()

	io.Copy(dst, f)

	return nil
}

func copyFiles(specFile string) error {
	f, err := os.Open(specFile)
	if err != nil {
		return errors.Wrap(err, "unable to open spec file")
	}

	defer f.Close()

	s := bufio.NewScanner(f)
	for s.Scan() {
		parts := strings.Split(s.Text(), " => ")
		if len(parts) != 2 {
			continue
		}

		src := os.ExpandEnv(parts[0])
		dst := os.ExpandEnv(parts[1])

		if err := copyFile(src, dst); err != nil {
			return errors.Wrap(err, "copy file error")
		}
	}

	return s.Err()
}

func copyFile(src, dst string) error {
	df, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer df.Close()

	return writeFileTo(df, src)
}

package auth_test

import (
	"context"
	"testing"

	"github.com/kopia/kopia/internal/auth"
)

func TestAuthentication(t *testing.T) {
	a := auth.AuthenticateSingleUser("user1", "password1")
	verifyAuthenticator(t, a, "user1", "password1", true)
	verifyAuthenticator(t, a, "user1", "password2", false)
	verifyAuthenticator(t, a, "user1", "password11", false)
	verifyAuthenticator(t, a, "user1a", "password1", false)
	verifyAuthenticator(t, a, "user1a", "password1a", false)
}

func TestCombineAuthenticators_Empty(t *testing.T) {
	a := auth.CombineAuthenticators()
	if a != nil {
		t.Fatal("combined authenticator expected to return nil for zero-length input")
	}
}

func TestCombineAuthenticators(t *testing.T) {
	a1 := auth.AuthenticateSingleUser("user1", "password1")
	a2 := auth.AuthenticateSingleUser("user2", "password2")
	a3 := auth.AuthenticateSingleUser("user3", "password3")

	a := auth.CombineAuthenticators(a1, a2, a3)
	verifyAuthenticator(t, a, "user1", "password1", true)
	verifyAuthenticator(t, a, "user2", "password2", true)
	verifyAuthenticator(t, a, "user3", "password3", true)
	verifyAuthenticator(t, a, "user1", "password2", false)
}

func verifyAuthenticator(t *testing.T, a auth.Authenticator, username, password string, want bool) {
	t.Helper()

	if got := a.IsValid(context.Background(), nil, username, password); got != want {
		t.Errorf("invalid authenticator result for %v/%v: %v, want %v", username, password, got, want)
	}
}

package auth_test

import (
	"context"
	"strconv"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/kopia/kopia/internal/auth"
	"github.com/kopia/kopia/internal/repotesting"
	"github.com/kopia/kopia/internal/user"
	"github.com/kopia/kopia/repo"
)

func TestRepositoryAuthenticator(t *testing.T) {
	a := auth.AuthenticateRepositoryUsers()
	ctx, env := repotesting.NewEnvironment(t, repotesting.FormatNotImportant)

	require.NoError(t, repo.WriteSession(ctx, env.Repository, repo.WriteSessionOptions{},
		func(ctx context.Context, w repo.RepositoryWriter) error {
			testProfile := user.Profile{
				Username:            "user1@host1",
				PasswordHashVersion: user.ScryptHashVersion,
			}

			err := testProfile.SetPassword("password1")
			if err != nil {
				return err
			}

			err = user.SetUserProfile(ctx, w, &testProfile)
			if err != nil {
				return err
			}

			return nil
		}))

	// valid user, valid password
	verifyRepoAuthenticator(ctx, t, a, env.Repository, "user1@host1", "password1", true)
	// valid user, invalid password
	verifyRepoAuthenticator(ctx, t, a, env.Repository, "user1@host1", "password2", false)
	// valid user, invalid password
	verifyRepoAuthenticator(ctx, t, a, env.Repository, "user1@host1", "password11", false)
	// invalid user, existing password
	verifyRepoAuthenticator(ctx, t, a, env.Repository, "user1@host1a", "password1", false)
	// invalid user, invalid password
	verifyRepoAuthenticator(ctx, t, a, env.Repository, "user1@host1a", "password1a", false)
}

func TestRepositoryAuthenticatorPasswordHashVersion(t *testing.T) {
	for _, tc := range []struct {
		profile  *user.Profile
		password string
	}{
		{
			profile: &user.Profile{
				Username:            "user2@host2",
				PasswordHashVersion: user.ScryptHashVersion,
			},
			password: "password2",
		},
		{
			profile: &user.Profile{
				Username: "user3@host3",
				// PasswordHashVersion is not set
			},
			password: "password3",
		},
		{
			profile: &user.Profile{
				Username:            "user4@host4",
				PasswordHashVersion: user.Pbkdf2HashVersion,
			},
			password: "password4",
		},
	} {
		t.Run(strconv.Itoa(tc.profile.PasswordHashVersion), func(t *testing.T) {
			a := auth.AuthenticateRepositoryUsers()
			ctx, env := repotesting.NewEnvironment(t, repotesting.FormatNotImportant)

			require.NoError(t, repo.WriteSession(ctx, env.Repository, repo.WriteSessionOptions{},
				func(ctx context.Context, w repo.RepositoryWriter) error {
					err := tc.profile.SetPassword(tc.password)
					if err != nil {
						return err
					}

					err = user.SetUserProfile(ctx, w, tc.profile)
					if err != nil {
						return err
					}

					return nil
				}))

			verifyRepoAuthenticator(ctx, t, a, env.Repository, tc.profile.Username, tc.password, true)
		})
	}
}

func verifyRepoAuthenticator(ctx context.Context, t *testing.T, a auth.Authenticator, r repo.Repository, username, password string, want bool) {
	t.Helper()

	got := a.IsValid(ctx, r, username, password)
	assert.Equal(t, want, got, "invalid authenticator result for %v/%v", username, password)
}

